-- FASE 3 ter — Capa de jurisdicciones del D.S. 991/1987.
-- GENERADO por scripts/fase3ter_construir_capa.py (INV-3.7). No editar.
-- DECRETO   : paralelos, poligonales completas, rol_cadena, y la extension
--             mar afuera del Art. 2.
-- CONVENCION: separacion lateral en la franja oceanica, 200 mn como limite
--             exterior (370400 m), y cierre generoso hacia tierra con
--             resta posterior de la capa de tierra.

-- ST_MakeValid en fid 1738 LAGO GENERAL CARRERA: Ring Self-intersection[-71.838715429267 -46.4804906410751]
--   antes=0.111516828410 despues=0.111516828410 dif=3.469e-16

BEGIN;
DROP TABLE IF EXISTS jurisdicciones_decreto;
CREATE TABLE jurisdicciones_decreto (
  id TEXT PRIMARY KEY, nombre TEXT NOT NULL, gobernacion TEXT NOT NULL,
  ambito TEXT NOT NULL CHECK (ambito IN ('maritima','lacustre','antartica','insular_remota')),
  participa_matching BOOLEAN NOT NULL, sin_georreferenciar BOOLEAN NOT NULL,
  estado_geometria TEXT NOT NULL CHECK (estado_geometria IN ('construida','nula_declarada','nula_no_determinada')),
  metodo TEXT, rol_cadena TEXT, causa_sin_geom TEXT, texto_decreto TEXT NOT NULL,
  geom geometry(MultiPolygon, 4326));

