INSERT INTO jurisdicciones_decreto VALUES ('lebu', 'Lebu',
  'Talcahuano', 'maritima', TRUE, FALSE,
  'construida', 'banda_paralelos', NULL,
  NULL, 'Desde el paralelo 37 26 00 S (ribera Norte del rio Quiapo) por el Norte, hasta el paralelo 38 30 00 S (Punta Manuel), limite Sur de la Region del Bio Bio. Incluye la Isla Mocha y los Lagos Lanalhue y Lleu Lleu.', ST_Multi(ST_MakeEnvelope(-85.0, -38.5, -65.0, -37.433333, 4326)));
