INSERT INTO jurisdicciones_decreto VALUES ('puerto_montt', 'Puerto Montt',
  'Puerto Montt', 'maritima', TRUE, FALSE,
  'construida', 'anillo_vertices', NULL,
  NULL, 'Hacia el Norte y el Este a partir desde Punta Capacho (41 39 00 S / 073 03 54 W), el litoral del Seno Reloncavi y el litoral continental hasta Caleta El Milagro (41 42 15 S / 072 38 30 W), desde alli la linea imaginaria que la une hasta la Punta Morro Chico (41 44 00 S / 072 39 04 W), continuando hacia el Sur por el litoral hasta Punta Trentelgue (41 54 42 S / 072 53 00 W). Desde Punta Trentelgue hasta el punto ubicado en 41 39 00 S / 072 52 30 W y desde este punto hasta Punta Capacho. Incluye las islas Tenglo, Maillen e islotes Caicura y lago Chapo.', ST_Multi(ST_GeomFromText('MULTIPOLYGON (((-72.651111 -41.733333, -72.883333 -41.911667, -72.87577106790062 -41.674212531423315, -72.641667 -41.704167, -72.651111 -41.733333)), ((-72.875 -41.65, -72.87577106790062 -41.674212531423315, -73.065 -41.65, -72.875 -41.65)))', 4326)));
INSERT INTO jurisdicciones_decreto VALUES ('maullin', 'Maullin',
  'Puerto Montt', 'maritima', TRUE, FALSE,
  'construida', 'poligonal_rol_S', 'S',
  NULL, 'Por el norte el paralelo 40 14 30 S (Ribera Sur del rio Bueno) limite sur de la Region de Los Rios, y por el sur el paralelo 41 44 40 S, luego desde el punto ubicado en 41 44 40 S / 073 45 00 W (Punta Chocoi) una linea imaginaria hasta el punto en 41 47 00 S / 073 31 30 W. Incluye la isla Dona Sebastiana y el rio Maicolpue.', ST_Multi(ST_GeomFromText('POLYGON ((-85 -41.783333, -85 -40.241667, -82.4446135153903 -40.241667, -65 -40.241667, -65 -41.783333, -73.525 -41.783333, -85 -41.783333))', 4326)));
INSERT INTO jurisdicciones_decreto VALUES ('calbuco', 'Calbuco',
  'Puerto Montt', 'maritima', TRUE, FALSE,
  'construida', 'anillo_vertices', NULL,
  NULL, 'Por el Norte, hacia el Sur, el litoral desde la Punta Capacho (41 39 00 S / 073 03 54 W), hasta el punto ubicado en 41 47 00 S / 073 31 30 W, desde alli la linea imaginaria que sigue por los puntos ubicados en 42 00 00 S / 073 00 00 W, Punta Trentelgue (41 54 42 S / 072 53 00 W), 41 39 00 S / 072 52 30 W y desde este punto hasta Punta Capacho. Incluye las islas Guar, Puliqui, Queulin, Tabon, Quihua, Abato, Lin y Chidguapi.', ST_Multi(ST_GeomFromText('POLYGON ((-73.065 -41.65, -73.525 -41.783333, -73 -42, -72.883333 -41.911667, -72.875 -41.65, -73.065 -41.65))', 4326)));
INSERT INTO jurisdicciones_decreto VALUES ('hornopiren', 'Rio Negro Hornopiren',
  'Puerto Montt', 'maritima', TRUE, FALSE,
  'construida', 'anillo_vertices', NULL,
  NULL, 'Por el Norte, desde la Punta Trentelgue (41 54 42 S / 072 53 00 W) siguiendo hacia el Sur por el litoral Weste de Chiloe Continental hasta la interseccion del paralelo 42 30 00 S con la longitud 072 38 00 W en la costa Este del estero Renihue, luego por el paralelo 42 30 00 S hacia el Weste hasta la Longitud 073 00 00 W, continuando por este meridiano hacia el Norte hasta la Latitud 42 00 00 S y desde alli hasta Punta Trentelgue. Incluye las islas Malomacun, Toro, Linguar, Llanchid, Cuchillo, Lobos, Cabras, Pelada, Llancahue, Liliguapi e isla Ica (a traves peninsula Huequi).', ST_Multi(ST_GeomFromText('POLYGON ((-72.883333 -41.911667, -72.633333 -42.5, -73 -42, -72.883333 -41.911667))', 4326)));
INSERT INTO jurisdicciones_decreto VALUES ('cochamo', 'Cochamo',
  'Puerto Montt', 'maritima', TRUE, FALSE,
  'construida', 'poligonal_rol_W', 'W',
  NULL, 'Las aguas y el litoral del Estero Reloncavi, desde la linea imaginaria que une Morro Chico (41 44 00 S / 072 39 04 W) y Caleta El Milagro (41 42 15 S / 072 38 30 W). Incluye los Farellones Marimelli y los Lagos Tagua-Tagua e Inferior.', ST_Multi(ST_GeomFromText('POLYGON ((-72.641667 -41.704167, -65 -41.704167, -65 -41.733333, -72.651111 -41.733333, -72.641667 -41.704167))', 4326)));
INSERT INTO jurisdicciones_decreto VALUES ('ancud', 'Ancud',
  'Castro', 'maritima', TRUE, FALSE,
  'construida', 'poligonal_rol_SE', 'SE',
  NULL, 'Por el Norte, el paralelo 41 44 40 S hasta Punta Chocoi (41 44 40 S / 073 45 00 W), y desde alli la linea imaginaria que une Punta Chocoi con los puntos ubicados en 41 47 00 S / 073 31 30 W, 42 00 00 S / 073 00 00 W; y desde alli hacia el Weste.', ST_Multi(ST_GeomFromText('POLYGON ((-73 -42, -85 -42, -85 -41.744444, -73.75 -41.744444, -73.525 -41.783333, -73 -42))', 4326)));
INSERT INTO jurisdicciones_decreto VALUES ('quemchi', 'Quemchi',
  'Castro', 'maritima', TRUE, FALSE,
  'construida', 'poligonal_rol_S', 'S',
  NULL, 'Por el Norte el paralelo 42 00 00 S desde el meridiano 073 00 00 W hacia el Weste y por el Sur, la linea imaginaria que parte desde el punto ubicado en 42 23 30 S / 073 17 00 W, Punta NE de isla Meulin; la Punta Tenaun (42 20 00 S / 073 21 30 W), continuando posteriormente por el paralelo 42 20 00 S hacia el Weste. Incluye las islas Caucahue, Butachauques, Mechuque, Anihue, Taucolon, Cheniao, Tac y Aulin.', ST_Multi(ST_GeomFromText('POLYGON ((-85 -42.391667, -85 -42, -73.78689910210174 -42, -65 -42, -65 -42.391667, -73.283333 -42.391667, -85 -42.391667))', 4326)));
INSERT INTO jurisdicciones_decreto VALUES ('chaiten', 'Chaiten',
  'Castro', 'maritima', TRUE, FALSE,
  'construida', 'poligonal_rol_W', 'W',
  NULL, 'Por el Norte el paralelo 42 30 00 S desde su interseccion con Longitud 073 12 00 W hacia el Este, hasta la interseccion del paralelo 42 30 00 S con la longitud 072 38 00 W en la costa Este del estero Renihue; por el Weste, el meridiano 073 12 00 W entre los paralelos 42 30 00 S y 43 00 30 S, incluyendo las Islas Desertores, siguiendo el paralelo 43 00 30 S hacia el Weste hasta su interseccion con el Meridiano 073 15 00 W, luego hacia el Sur hasta el Paralelo 43 44 25 S y desde alli hacia el Este. Incluye el Lago Yelcho y el Lago Palena.', ST_Multi(ST_GeomFromText('POLYGON ((-73.2 -42.5, -65 -42.5, -65 -43.740278, -73.25 -43.740278, -73.25 -43.008333, -73.2 -43.008333, -73.2 -42.5))', 4326)));
INSERT INTO jurisdicciones_decreto VALUES ('achao', 'Achao',
  'Castro', 'maritima', TRUE, FALSE,
  'construida', 'anillo_poligonal', 'anillo',
  NULL, 'Area formada por la linea imaginaria que une la Punta Tenaun (42 20 00 S / 073 21 30 W) con la punta NW de la isla Meulin (42 23 30 S / 073 17 00 W), desde alli siguiendo el paralelo 42 23 30 S hacia el Este hasta el meridiano 073 00 00 W; luego, desde este meridiano, hacia el Sur hasta la Latitud 42 30 00 S; luego hacia el Weste hasta su interseccion con la Longitud 073 12 00 [S sic]; desde este punto hacia el Sur hasta su interseccion con la Latitud 42 39 40 S y desde este punto hacia el Weste hasta la Longitud 073 23 50 W; luego hacia el Norte por esa Longitud hasta la punta Cheguian en isla Quinchao (42 35 12 S / 073 23 50 W), y desde esta punta la diagonal hasta la punta Pindo en isla Chelin (42 32 50 S / 073 30 30 W), y desde esta punta hasta el punto ubicado en 42 28 00 S / 073 38 40 W, punta SW de la Isla Quinchao; desde este punto hasta la punta NW de la isla Quinchao (42 23 30 S / 073 39 30 W) y desde este punto hasta la Punta Tenaun. Incluye las Islas Quinchao, Lin Lin, Meulin, Caguache, Lingua, Quenac, Teuquelin, Alao, Chaulinec y Apiao.', ST_Multi(ST_GeomFromText('POLYGON ((-73.358333 -42.333333, -73.283333 -42.391667, -73 -42.391667, -73 -42.5, -73.2 -42.5, -73.2 -42.661111, -73.397222 -42.661111, -73.397222 -42.586667, -73.508333 -42.547222, -73.644444 -42.466667, -73.658333 -42.391667, -73.358333 -42.333333))', 4326)));
INSERT INTO jurisdicciones_decreto VALUES ('castro', 'Castro',
  'Castro', 'maritima', TRUE, FALSE,
  'construida', 'poligonal_rol_SE', 'SE',
  NULL, 'Por el Norte el paralelo 42 20 00 S hasta el Faro Punta Tenaun (42 20 00 S / 073 21 30 W), desde alli la linea imaginaria que une la Punta NW de la isla Quinchao (42 23 30 S / 073 39 30 W), Punta SW de la Isla Quinchao (42 28 00 S / 073 38 40 W), luego la diagonal hasta la Punta Pindo en Isla Chelin (42 32 50 S / 073 30 30 W), y desde esta punta hasta Punta Cheguian, Isla Quinchao (42 35 12 S / 073 23 50 W), luego hacia el Sur por la Longitud 073 23 50 W hasta su interseccion con la Latitud 42 39 40 S, desde este punto hacia el Weste hasta la Longitud 073 33 30 W, luego hacia el Norte hasta la Latitud 42 33 30 S, luego hacia el Weste hasta la Longitud 073 37 00 W, luego al Sur hasta la Latitud 42 35 00 S, y desde este punto hacia el Weste. Incluye las Islas Chelin y Quehui.', ST_Multi(ST_GeomFromText('POLYGON ((-73.616667 -42.661111, -85 -42.661111, -85 -42.333333, -73.358333 -42.333333, -73.658333 -42.391667, -73.644444 -42.466667, -73.508333 -42.547222, -73.397222 -42.586667, -73.397222 -42.661111, -73.558333 -42.661111, -73.616667 -42.661111))', 4326)));
INSERT INTO jurisdicciones_decreto VALUES ('chonchi', 'Chonchi',
  'Castro', 'maritima', TRUE, FALSE,
  'construida', 'poligonal_rol_NE', 'NE',
  NULL, 'Desde el paralelo 42 35 00 S por el Norte, hasta su interseccion con el meridiano 073 37 00 W, desde alli hacia el Norte hasta la Latitud 42 33 30 S, luego hacia el Este hasta la Longitud 073 33 30 W, luego hacia el Sur hasta la Latitud 42 39 40 S, desde este punto hacia el Este hasta su interseccion con la Longitud 073 12 00 W, continuando por este meridiano hacia el Sur hasta la Latitud 43 00 30 S, desde alli hacia el Weste hasta la Punta Centinela (43 00 30 S / 073 19 30 W), luego la diagonal hasta el punto ubicado en 42 55 20 S / 073 36 10 W, luego hacia el Norte por esta longitud hasta la Latitud 42 53 10 S, desde este punto la diagonal hasta el punto ubicado en 42 50 00 S / 073 45 00 W, siguiendo por esta Latitud hacia el Weste. Incluye la Isla Lemuy y el borde NE de la Isla Tranqui.', ST_Multi(ST_GeomFromText('POLYGON ((-73.616667 -43.008333, -85 -43.008333, -85 -42.558333, -74.5171008753648 -42.558333, -73.616667 -42.558333, -73.616667 -42.583333, -73.616667 -42.881131896048146, -73.602778 -42.886111, -73.602778 -42.922222, -73.325 -43.008333, -73.616667 -43.008333))', 4326)));
INSERT INTO jurisdicciones_decreto VALUES ('quellon', 'Quellon',
  'Castro', 'maritima', TRUE, FALSE,
  'construida', 'poligonal_rol_NE', 'NE',
  NULL, 'Por el Norte, el paralelo 42 50 00 S hasta su interseccion con la Longitud 073 45 00 W, y desde este punto la diagonal hasta el punto ubicado en 42 53 10 S / 073 36 10 W, luego hacia el Sur por esta longitud hasta su interseccion con la Latitud 42 55 20 S, luego la diagonal hasta la Punta Centinela (43 00 30 S / 073 19 30 W), y desde esta punta hacia el Este hasta su interseccion con la Longitud 073 15 00 W, luego hacia el Sur por este Meridiano hasta la Latitud 43 44 25 S, y desde alli hacia el Weste.', ST_Multi(ST_GeomFromText('POLYGON ((-73.25 -43.740278, -85 -43.740278, -85 -42.833333, -73.75 -42.833333, -73.602778 -42.886111, -73.602778 -42.922222, -73.325 -43.008333, -73.25 -43.008333, -73.25 -43.740278))', 4326)));
INSERT INTO jurisdicciones_decreto VALUES ('melinka', 'Melinka',
  'Aysen', 'maritima', TRUE, FALSE,
  'construida', 'poligonal_rol_E', 'E',
  NULL, 'Desde el paralelo 43 44 25 S (Punta Guala) por el Norte, hasta el paralelo 44 46 54 S (Islote Cayo Blanco) por el Sur. Por el Este la linea imaginaria que divide el Canal Moraleda entre los siguientes puntos: 43 44 25 S / 073 30 00 W; 43 59 07 S / 073 27 13 W (Islote Locos); 44 16 00 S / 073 24 00 W (Roca Chacabuco); 44 46 54 S / 073 32 30 W (Islote Cayo Blanco).', ST_Multi(ST_GeomFromText('POLYGON ((-73.541667 -44.781667, -85 -44.781667, -85 -43.740278, -73.5 -43.740278, -73.453611 -43.985278, -73.4 -44.266667, -73.541667 -44.781667))', 4326)));
INSERT INTO jurisdicciones_decreto VALUES ('puerto_cisnes', 'Puerto Cisnes',
  'Aysen', 'maritima', TRUE, FALSE,
  'construida', 'poligonal_rol_W', 'W',
  NULL, 'Desde el paralelo 43 44 25 S (Punta Guala) por el Norte, hasta el paralelo 44 57 15 S (Punta San Andres - Canal Puyuhuapi) por el Sur. Por el Weste la linea imaginaria que divide el Canal Moraleda entre los siguientes puntos: 43 44 25 S / 073 30 00 W; 43 59 07 S / 073 27 13 W (Islote Locos); 44 16 00 S / 073 24 00 W (Roca Chacabuco); 44 46 54 S / 073 32 30 W (Islote Cayo Blanco); 44 57 15 S / 073 21 40 W (Punta San Andres).', ST_Multi(ST_GeomFromText('POLYGON ((-73.5 -43.740278, -65 -43.740278, -65 -44.954167, -73.361111 -44.954167, -73.541667 -44.781667, -73.4 -44.266667, -73.453611 -43.985278, -73.5 -43.740278))', 4326)));
INSERT INTO jurisdicciones_decreto VALUES ('puerto_aguirre', 'Puerto Aguirre',
  'Aysen', 'maritima', TRUE, FALSE,
  'construida', 'poligonal_rol_S', 'S',
  NULL, 'Por el Norte el paralelo 44 46 54 S hasta el Islote Cayo Blanco (44 46 54 S / 073 32 30 W) y desde este punto la linea imaginaria que une los siguientes puntos: 44 57 15 S / 073 21 40 W (Punta San Andres), 45 14 45 S / 073 16 24 W (Puerto Perez), 45 22 18 S / 073 29 30 W (Islote Rodriguez), 45 27 48 S / 073 33 07 W (Isla Traiguen) y desde este ultimo punto por el paralelo 45 27 48 S al Weste.', ST_Multi(ST_GeomFromText('POLYGON ((-85 -45.463333, -85 -44.781667, -73.541667 -44.781667, -65 -44.781667, -65 -45.463333, -73.551944 -45.463333, -85 -45.463333))', 4326)));
INSERT INTO jurisdicciones_decreto VALUES ('puerto_chacabuco', 'Puerto Chacabuco',
  'Aysen', 'maritima', TRUE, FALSE,
  'construida', 'poligonal_rol_N', 'N',
  NULL, 'Por el Norte desde la linea imaginaria conformada desde el Este por el paralelo 44 57 15 S, hasta punta San Andres (44 57 15 S / 073 21 40 W) continuando en diagonal entre los puntos 45 14 45 S / 073 16 24 W (Puerto Perez); 45 22 18 S / 073 29 30 W (Islote Rodriguez), 45 27 48 S / 073 33 07 W (Isla Traiguen) y desde este ultimo punto por el paralelo 45 27 48 S hacia el Weste. Por el Sur el paralelo 47 00 00 S incluyendo los canales interiores hasta la Laguna San Rafael inclusive. Excluye el Lago General Carrera.', ST_Multi(ST_GeomFromText('POLYGON ((-85 -47, -85 -44.954167, -73.361111 -44.954167, -65 -44.954167, -65 -47, -74.5624132771475 -47, -85 -47))', 4326)));
