INSERT INTO jurisdicciones_decreto VALUES ('baker', 'Baker',
  'Aysen', 'maritima', TRUE, FALSE,
  'nula_no_determinada', NULL, NULL,
  'el decreto no entrega con que cerrar: falta limite sur. No se toma del vecino.', 'Desde el paralelo 47 00 00 S por el Norte hasta el limite Sur de la Region de Aysen del General Carlos Ibanez del Campo, por el Sur; excluye los Lagos Cochrane y O''Higgins.', NULL);
INSERT INTO jurisdicciones_decreto VALUES ('puerto_eden', 'Puerto Eden',
  'Punta Arenas', 'maritima', TRUE, FALSE,
  'nula_no_determinada', NULL, NULL,
  'el decreto no entrega con que cerrar: falta limite norte. No se toma del vecino.', 'Desde el limite Sur de la Gobernacion Maritima de Aisen por el Norte, hasta el paralelo 50 33 00 S por el Sur.', NULL);
INSERT INTO jurisdicciones_decreto VALUES ('puerto_natales', 'Puerto Natales',
  'Punta Arenas', 'maritima', TRUE, FALSE,
  'construida', 'banda_paralelos', NULL,
  NULL, 'Desde el paralelo 50 33 00 S por el Norte, hasta el paralelo 52 30 30 S por el Sur.', ST_Multi(ST_MakeEnvelope(-85.0, -52.508333, -65.0, -50.55, 4326)));
INSERT INTO jurisdicciones_decreto VALUES ('punta_arenas', 'Punta Arenas',
  'Punta Arenas', 'maritima', TRUE, FALSE,
  'construida', 'banda_paralelos', NULL,
  NULL, 'Desde el paralelo 52 30 30 S por el Norte hasta la linea imaginaria que une Punta Harry con Cabo San Vicente, en la Segunda Angostura del Estrecho de Magallanes; y de alli a Punta Anxius, siguiendo la costa Weste de la Isla Dawson, los Canales Magdalena y Cockburn y la totalidad de las aguas de los senos adyacentes hasta la Peninsula Brecknock y luego por el paralelo 54 33 00 S hacia el Oceano Pacifico.', ST_Multi(ST_MakeEnvelope(-85.0, -54.55, -65.0, -52.508333, 4326)));
INSERT INTO jurisdicciones_decreto VALUES ('punta_delgada', 'Punta Delgada',
  'Punta Arenas', 'maritima', FALSE, TRUE,
  'nula_declarada', NULL, NULL,
  'Limites definidos por accidentes geograficos sin coordenadas (Punta Harry, Cabo San Vicente). Requiere georreferenciacion externa.', 'El Estrecho de Magallanes desde la linea imaginaria que une punta Harry y Cabo San Vicente, hasta el limite maritimo internacional por el Oriente.', NULL);
INSERT INTO jurisdicciones_decreto VALUES ('tierra_del_fuego', 'Tierra del Fuego',
  'Punta Arenas', 'maritima', FALSE, TRUE,
  'nula_declarada', NULL, NULL,
  'Limites definidos por accidentes geograficos sin coordenadas (Cabo San Vicente, Punta Anxius). Requiere georreferenciacion externa.', 'El area oriental de la linea imaginaria que une Cabo San Vicente por el Norte, hasta Punta Anxius por el Sur. Incluye Bahia Gente Grande, Bahia Inutil, ambas riberas del Canal Whiteside, Canal Gabriel y Seno Almirantazgo con la totalidad de las aguas de Senos y Bahias adyacentes.', NULL);
INSERT INTO jurisdicciones_decreto VALUES ('puerto_williams', 'Puerto Williams',
  'Puerto Williams', 'maritima', TRUE, FALSE,
  'nula_declarada', NULL, NULL,
  'No cerrable con el decreto: el limite norte pasa por el ''hito N 26'' del Canal Beagle, que el texto nombra sin coordenadas, y por ''la delimitacion existente del Canal Beagle''. Falta dato de fuente, no de transcripcion.', 'El area que limita por el Norte con el Limite Politico Internacional con Argentina desde el punto A (55 07 18 S / 066 25 00 W), siguiendo hacia el Weste la delimitacion existente del Canal Beagle hasta el hito N 26 y desde alli todas las aguas interiores, islas e islotes al Sur de la isla Grande de Tierra del Fuego. Al Este, con el Limite Politico Internacional con Argentina desde el punto A hasta el punto F (58 21 06 S / 067 16 00 W) y desde este ultimo punto hacia el Sur por el meridiano 067 16 00 W hasta el limite Norte de la Gobernacion Maritima de la Antartica Chilena, en el Paso Drake, y hacia el Weste, en el Oceano Pacifico, siguiendo el contorno continental hasta el paralelo 54 33 00 S.', NULL);
INSERT INTO jurisdicciones_decreto VALUES ('bahia_fildes', 'Bahia Fildes',
  'Antartica Chilena', 'antartica', TRUE, FALSE,
  'construida', 'anillo_vertices', NULL,
  NULL, 'Area delimitada por las lineas imaginarias que unen: 57 42 00 S / 053 00 00 W; 61 30 00 S / 053 00 00 W; 62 50 00 S / 059 16 00 W; 58 15 00 S / 059 30 00 W; 57 42 00 S / 057 50 00 W; 57 42 00 S / 053 00 00 W.', ST_Multi(ST_GeomFromText('POLYGON ((-53 -57.7, -53 -61.5, -59.266667 -62.833333, -59.5 -58.25, -57.833333 -57.7, -53 -57.7))', 4326)));
