  'construida', 'anillo_vertices', NULL,
  NULL, 'Area delimitada por las lineas imaginarias que unen: 62 50 00 S / 059 16 00 W; 58 15 00 S / 059 30 00 W; 59 45 00 S / 065 15 00 W; 63 15 00 S / 070 45 00 W; 65 00 00 S / 075 15 00 W; 62 50 00 S / 059 16 00 W.', ST_Multi(ST_GeomFromText('POLYGON ((-59.266667 -62.833333, -59.5 -58.25, -65.25 -59.75, -70.75 -63.25, -75.25 -65, -59.266667 -62.833333))', 4326)));
INSERT INTO jurisdicciones_decreto VALUES ('rada_covadonga', 'Rada Covadonga',
