INSERT INTO jurisdicciones_decreto VALUES ('bahia_paraiso', 'Bahia Paraiso',
  'Antartica Chilena', 'antartica', TRUE, FALSE,
  'construida', 'anillo_vertices', NULL,
  NULL, 'Area delimitada por las lineas imaginarias que unen: 70 00 00 S / 053 00 00 W; 62 50 00 S / 059 16 00 W; 65 00 00 S / 075 15 00 W; 69 15 00 S / 090 00 00 W.', ST_Multi(ST_GeomFromText('POLYGON ((-53 -70, -59.266667 -62.833333, -75.25 -65, -90 -69.25, -53 -70))', 4326)));

CREATE TEMP TABLE _tierra AS
SELECT ST_Subdivide(ST_MakeValid(geom), 256) AS geom FROM mapa_base_multipoligonos
WHERE geom && ST_MakeEnvelope(-85.0, -60, -65.0, -17, 4326)
UNION ALL
SELECT ST_Subdivide(ST_MakeValid(ST_Intersection(ST_MakeValid(geom),
       ST_MakeEnvelope(-85.0, -60, -65.0, -17, 4326))), 256) FROM ne_land
WHERE ST_Intersects(geom, ST_MakeEnvelope(-85.0, -60, -65.0, -17, 4326));
CREATE INDEX ON _tierra USING GIST (geom);
ANALYZE _tierra;

-- Limite exterior. OJO: hay que RECORTAR ne_land al bbox ANTES de unir y
-- buffear. ne_land trae un poligono con toda la tierra del mundo; buffearlo
-- entero en espacio geography da una geometria degenerada que cubre el globo,
-- y entonces el recorte no recorta nada y los poligonos se quedan pegados al
-- borde arbitrario de la caja en vez del limite exterior del Art. 2.
CREATE TEMP TABLE _zee AS
SELECT ST_ReducePrecision(ST_MakeValid(ST_Buffer(
  ST_Simplify(ST_Union(ST_MakeValid(ST_Intersection(ST_MakeValid(l.geom),
    ST_MakeEnvelope(-85.0, -60, -65.0, -17, 4326)))), 0.01)::geography,
  370400)::geometry), 1e-8) AS geom FROM ne_land l
WHERE ST_Intersects(l.geom, ST_MakeEnvelope(-85.0, -60, -65.0, -17, 4326));

-- Acotar al limite exterior todo lo maritimo que se extiende mar afuera.
UPDATE jurisdicciones_decreto j SET geom = ST_Multi(ST_CollectionExtract(ST_MakeValid(
  ST_Intersection(ST_ReducePrecision(j.geom, 1e-8), z.geom)), 3))
FROM _zee z WHERE j.ambito = 'maritima' AND j.geom IS NOT NULL;

-- Restar tierra. Solo maritima.
UPDATE jurisdicciones_decreto j SET geom = ST_Multi(ST_CollectionExtract(ST_MakeValid(
  ST_Difference(ST_ReducePrecision(j.geom, 1e-8), t.geom)), 3))
FROM (SELECT j2.id, ST_ReducePrecision(ST_MakeValid(
        ST_UnaryUnion(ST_Collect(t2.geom))), 1e-8) AS geom
      FROM jurisdicciones_decreto j2 JOIN _tierra t2
        ON t2.geom && j2.geom AND ST_Intersects(t2.geom, j2.geom)
      WHERE j2.ambito = 'maritima' AND j2.geom IS NOT NULL
      GROUP BY j2.id) t WHERE j.id = t.id;

UPDATE jurisdicciones_decreto SET geom = ST_MakeValid(geom) WHERE geom IS NOT NULL AND NOT ST_IsValid(geom);
CREATE INDEX idx_jurisdicciones_decreto_geom ON jurisdicciones_decreto USING GIST (geom);
CREATE INDEX idx_jurisdicciones_decreto_ambito ON jurisdicciones_decreto (ambito);
ANALYZE jurisdicciones_decreto;
COMMIT;